# Writes the generated part of the differential corpus of cg-rv64:
# one program per integer type with tables of edge values, and the trap
# program. Run from the package folder:
#
#     python -I tests/tools/gen_corpus.py tests/programs
#
# The output is committed; this script is kept so the tables can be read
# and changed in one place. It uses the standard library only.
import sys

TYPES = [("i8", 8, True), ("i16", 16, True), ("i32", 32, True), ("i64", 64, True),
         ("u8", 8, False), ("u16", 16, False), ("u32", 32, False), ("u64", 64, False)]
MAIN = ("fn main() ~ Console + Process + Environment {\n"
        "    run(args_get(1).parse_int() as u64);\n}\n")


def lit(v, t):
    """A literal of type t. The smallest signed value has no literal."""
    name, bits, signed = t
    if signed and v == -(1 << (bits - 1)):
        return "(-%d_%s - 1_%s)" % ((1 << (bits - 1)) - 1, name, name)
    if v < 0:
        return "-%d_%s" % (-v, name)
    return "%d_%s" % (v, name)


def edge_values(t):
    name, bits, signed = t
    if signed:
        lo, hi = -(1 << (bits - 1)), (1 << (bits - 1)) - 1
        return [lo, lo + 1, -2, -1, 0, 1, 2, hi - 1, hi]
    hi = (1 << bits) - 1
    return [0, 1, 2, 3, hi // 2, hi // 2 + 1, hi - 1, hi]


def table(t):
    name = t[0]
    out = ["fn val(i: u64) -> %s {" % name]
    vals = edge_values(t)
    for i, v in enumerate(vals[:-1]):
        out.append("    if i == %d_u64 { return %s; }" % (i, lit(v, t)))
    out.append("    %s" % lit(vals[-1], t))
    out.append("}")
    return out, len(vals)


def ops(t):
    name, bits, signed = t
    lo = lit(-(1 << (bits - 1)), t) if signed else None
    z, one = lit(0, t), lit(1, t)
    out = ["fn ops(a: %s, b: %s) ~ Console {" % (name, name),
           "    let wa = a.wrapping_add(b);",
           "    let ws = a.wrapping_sub(b);",
           "    let wm = a.wrapping_mul(b);",
           '    println!("{} {} w {} {} {}", a, b, wa, ws, wm);',
           '    println!(" c {} {} {} {} {} {}", a == b, a != b, a < b, a <= b, a > b, a >= b);',
           '    println!(" b {} {} {} {}", a & b, a | b, a ^ b, !a);']
    if signed:
        out += ["    if b != %s && !(a == %s && b == %s) { println!(\" d {} {}\", a / b, a %% b); }" % (z, lo, lit(-1, t)),
                "    if (b >= %s) == (wa >= a) { println!(\" + {}\", a + b); }" % z,
                "    if (b >= %s) == (ws <= a) { println!(\" - {}\", a - b); }" % z,
                "    let mut safe = a == %s;" % z,
                "    if a != %s && !(a == %s && wm == %s) { safe = wm / a == b; }" % (z, lit(-1, t), lo),
                "    if safe { println!(\" * {}\", a * b); }",
                "    if a != %s { println!(\" n {}\", -a); }" % lo]
    else:
        out += ["    if b != %s { println!(\" d {} {}\", a / b, a %% b); }" % z,
                "    if wa >= a { println!(\" + {}\", a + b); }",
                "    if a >= b { println!(\" - {}\", a - b); }",
                "    let mut safe = a == %s;" % z,
                "    if a != %s { safe = wm / a == b; }" % z,
                "    if safe { println!(\" * {}\", a * b); }"]
    out.append("}")
    return out


def single(t):
    name, bits, signed = t
    top = (1 << (bits - 1)) - 1 if signed else (1 << bits) - 1
    counts = [0, 1, bits - 1, bits, bits + 1, min(top, 2 * bits - 1), min(top, 200)]
    out = ["fn single(a: %s) ~ Console {" % name]
    for c in counts:
        out.append('    println!(" s%d {} {}", a << %s, a >> %s);' % (c, lit(c, t), lit(c, t)))
    casts = ", ".join("a as %s" % u[0] for u in TYPES)
    out.append('    println!(" x {} {} {} {} {} {} {} {}", %s);' % casts)
    out.append('    println!(" h {:x} {:08x} {:016x}", a as u32, a as u32, a as u64);')
    out.append("}")
    return out


def type_program(t):
    tab, n = table(t)
    body = ["// Generated by tests/tools/gen_corpus.py: edge values of %s." % t[0],
            "// Every operation that would trap is guarded, so the program ends with",
            "// status 0. The trap cases are in traps.bld.", ""]
    body += tab + [""] + ops(t) + [""] + single(t) + [""]
    body += ["fn run(k: u64) ~ Console {",
             "    let mut i: u64 = 0_u64;",
             "    while i < %d_u64 {" % n,
             "        single(val(i));",
             "        let mut j: u64 = 0_u64;",
             "        while j < %d_u64 {" % n,
             "            ops(val(i), val(j));",
             "            j = j + 1_u64;",
             "        }",
             "        i = i + 1_u64;",
             "    }",
             "}", "", MAIN]
    return "\n".join(body)


def trap_fn(t):
    name, bits, signed = t
    hi = lit((1 << (bits - 1)) - 1 if signed else (1 << bits) - 1, t)
    z, one, two = lit(0, t), lit(1, t), lit(2, t)
    out = ["fn trap_%s(op: u64) ~ Console {" % name,
           "    let hi: %s = %s;" % (name, hi),
           "    let zero: %s = %s;" % (name, z),
           "    let one: %s = %s;" % (name, one)]
    cases = ["hi + one", "zero - one" if not signed else "hi - (zero - one)", "hi * %s" % two,
             "hi / zero", "hi % zero", "(hi - one) + one"]
    if signed:
        out += ["    let lo: %s = %s;" % (name, lit(-(1 << (bits - 1)), t)),
                "    let m1: %s = %s;" % (name, lit(-1, t))]
        cases += ["lo + m1", "lo - one", "lo * m1", "-lo", "lo / m1", "lo % m1", "lo / one", "m1 * m1"]
    for i, c in enumerate(cases):
        out.append('    if op == %d_u64 { println!("{}", %s); }' % (i, c))
    out.append("}")
    return out, len(cases)


def write(folder, name, text):
    with open(folder + "/" + name, "w", newline="\n") as f:
        f.write(text)


def main():
    folder = sys.argv[1]
    for t in TYPES:
        write(folder, "edge_%s.bld" % t[0], type_program(t))
    for half, types in (("s", TYPES[:4]), ("u", TYPES[4:])):
        body = ["// Generated by tests/tools/gen_corpus.py: arithmetic traps of the",
                "// %s types. run(k) takes case k %% 16 of type k / 16. A case" % ("signed" if half == "s" else "unsigned"),
                "// that traps prints the case number, then the trap line, and ends with",
                "// status 101. tests/corpus.txt lists the range of k.", ""]
        run = ["fn run(k: u64) ~ Console {", '    println!("case {}", k);']
        for i, t in enumerate(types):
            fn, n = trap_fn(t)
            body += fn + [""]
            run.append("    if k / 16_u64 == %d_u64 { trap_%s(k %% 16_u64); }" % (i, t[0]))
        run += ['    println!("no trap");', "}", "", MAIN]
        write(folder, "traps_%s.bld" % half, "\n".join(body + run))


main()
